#!/usr/bin/env python3
"""Review actual local geometry attempts and measured depth-consistency diagnostics."""
import json,os,subprocess,sys
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from mesh_render import render_mesh
def read(p):return json.loads(p.read_text())
def font(n):
    try:return ImageFont.truetype('/System/Library/Fonts/Supplemental/Arial.ttf',n)
    except OSError:return ImageFont.load_default(size=n)
def main():
    import trimesh
    os.environ['MPLCONFIGDIR']=str(ROOT/'.cache/matplotlib')
    import matplotlib;matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    base=ROOT/'data/camera-battery-withdrawal-15fps/geometry';out=base/'stage3-local-progress.html'
    if out.exists():raise ValueError('Progress report already exists; preserve it')
    consistency=read(base/'local-battery-v3/consistency.json');moge=read(base/'local-battery-v2/moge-v1/metadata.json');fitted=read(base/'battery-fitted-v1/metadata.json');generative=read(base/'battery-reconstruction-v1/metadata.json')
    rows=consistency['frames'];times=np.array([r['timestamp_s'] for r in rows]);fig,axs=plt.subplots(2,1,figsize=(11.5,7),sharex=True,constrained_layout=True)
    curves=[('DA_heldout_pair_error','Original local depth','#a85e3a'),('MoGe_sharedK_heldout_pair_error','MoGe + shared intrinsics','#417bb4'),('corrected_heldout_pair_error','MoGe + depth-scale correction','#21806d')]
    for key,label,color in curves:
        values=[np.nan if r[key] is None or (key.startswith('corrected') and not r['correction_accepted']) else r[key]*100 for r in rows];axs[0].plot(times,values,label=label,color=color,lw=2)
    axs[0].set(ylabel='Median relative pair-distance error (%)',title='Internal shape consistency on held-out point IDs — not physical accuracy');axs[0].legend(loc='upper left',fontsize=9);axs[0].grid(alpha=.2)
    axs[1].plot(times,[r['estimated_hfov_degrees'] for r in moge['frames']],color='#417bb4',label='Per-frame MoGe estimate');axs[1].axhline(consistency['shared_hfov_degrees'],color='#21806d',linestyle='--',label=f"Shared estimate: {consistency['shared_hfov_degrees']:.1f}°")
    axs[1].set(xlabel='Source video time (s)',ylabel='Horizontal field of view (degrees)',title='Shared intrinsics assume unchanged optics in this short clip');axs[1].legend(fontsize=9);axs[1].grid(alpha=.2)
    for ax in axs:
        ax.axvline(times[15],color='#8a9ca8',linestyle=':',lw=1)
        ax.axvspan(times[-1]-.033,times[-1]+.033,color='#adb9c2',alpha=.3)
    fig.savefig(base/'stage3-consistency.png',dpi=160);plt.close(fig)
    meshes={};turntable=base/'battery-fitted-v1/turntable';turntable.mkdir(exist_ok=False)
    for name,path in [('fitted',base/'battery-fitted-v1/battery.glb'),('triposr',base/'battery-reconstruction-v1/battery-main.glb')]:
        mesh=trimesh.load(path,force='mesh');meshes[name]={'vertices':np.round(mesh.vertices,7).tolist(),'faces':mesh.faces.tolist(),'colors':np.asarray(mesh.visual.vertex_colors)[:,:3].tolist(),'normals':np.round(mesh.face_normals,6).tolist()}
        if name=='fitted':
            for i in range(60):
                canvas=Image.new('RGB',(800,720),'#edf2f5');canvas.paste(render_mesh(mesh,i*2*np.pi/60,size=(800,610)),(0,70));d=ImageDraw.Draw(canvas);d.text((22,14),'First closed battery asset / fitted shape prior',font=font(24),fill='#183244');d.text((22,47),'Proportions estimated from 7 views; hidden surfaces inferred.',font=font(17),fill='#526979');d.text((22,685),'Partial source appearance; neutral grey indicates inferred appearance.',font=font(17),fill='#526979');canvas.save(turntable/f'{i+1:06d}.jpg',quality=94)
            subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-framerate','15','-i',str(turntable/'%06d.jpg'),'-c:v','libx264','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart',str(base/'battery-fitted-v1/turntable.mp4')],check=True)
            Image.open(turntable/'000001.jpg').save(base/'battery-fitted-v1/preview.jpg',quality=95)
    metrics=consistency['median_heldout_relative_pair_errors'];summary=f"{metrics['DA_heldout_pair_error']*100:.1f}% → {metrics['MoGe_sharedK_heldout_pair_error']*100:.1f}% → {metrics['corrected_heldout_pair_error']*100:.1f}%"
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stage 3 / Consistent depth and first closed asset</title><style>
body{margin:0;background:#edf2f5;color:#183244;font:16px system-ui}main{max-width:1200px;margin:auto;padding:28px}h1{font-size:32px;margin-bottom:8px}.notice{padding:16px;background:#dce9ef;line-height:1.55}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:22px}.card{background:white;border:1px solid #d2dfe6;border-radius:10px;padding:18px}canvas{width:100%;height:460px;touch-action:none;cursor:grab;background:#142838;border-radius:6px}select,button{font:inherit;padding:8px;background:white;border:1px solid #9cb1bf;border-radius:5px;color:#183244}input{accent-color:#287c77}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #3285be}a{color:#1b689c}img,video{width:100%;border-radius:6px}.stats{font-size:25px;font-weight:650;color:#237768}.label{font-size:13px;color:#526979}li{margin:10px 0}.links a{display:inline-block;margin:4px 10px 4px 0}@media(max-width:800px){.grid{grid-template-columns:1fr}main{padding:16px}}
</style><main><h1>Stage 3 / Depth consistency + a closed battery asset</h1><p>Local MPS model runs, preserved baselines and evidence-linked geometry.</p><p class="notice">Stages 1–2 complete. Stage 3 remains in progress. The default mesh uses proportions estimated from video plus a cylindrical completion prior. It is neither a measured scan nor Meta SAM 3D output. Physical scale, exact terminals and hidden markings remain unknown.</p>
<div class="grid"><section class="card"><h2>Inspect the complete asset</h2><select id="model-select" aria-label="Model candidate"><option value="fitted">Evidence-fitted cylinder — local baseline</option><option value="triposr">TripoSR — rejected for wrong shape</option></select><p id="model-note"></p><canvas id="model" aria-label="Orbitable complete battery mesh"></canvas><p><label>Rotation <input id="angle" type="range" min="0" max="628" value="80"></label> <button id="reset">Reset view</button></p><p class="label">Drag to orbit; wheel to zoom. Each candidate is centred and normalized for inspection. This is not a video alignment.</p><p class="links"><a id="glb" href="battery-fitted-v1/battery.glb">Download GLB</a><a id="obj" href="battery-fitted-v1/battery.obj">Download OBJ</a><a id="provenance" href="battery-fitted-v1/metadata.json">Geometry provenance</a></p></section>
<section class="card"><h2>What changed</h2><p class="stats">ERROR_SUMMARY</p><p>Median held-out pair-distance inconsistency: original depth → MoGe/shared camera → corrected relative depth. This is an internal consistency check on 50 comparable non-reference frames, not a measured geometry error.</p><ul><li>MoGe-2 estimated a shared horizontal field of view of about 50.1°; the original local test assumed 60°.</li><li>Depth correction uses 42 point IDs. A disjoint set of 22 IDs supplies the check.</li><li>Final blurred sample 52 is withheld from 3D use because its required correction exceeds the bounds.</li><li>Seven views give a median battery length/diameter ratio of ASPECT_RATIO. Absolute dimensions remain unverified.</li><li>The fitted mesh is closed and watertight. About APPEARANCE_PERCENT% of its vertices receive nearby source appearance; the rest use neutral inferred appearance.</li></ul><p><a href="local-battery-v3/review-cotracker.html">Inspect the updated depth and tracks</a> · <a href="local-battery-v3/consistency.json">Consistency evidence</a></p></section></div>
<h2>Compare the depth evidence</h2><img src="stage3-consistency.png" alt="Held-out shape consistency and per-frame estimated field of view"><p class="label">The dotted line marks the reference observation. Grey marks the rejected final depth correction. Intrinsics are model estimates under a fixed-optics assumption, not physical calibration.</p>
<div class="grid"><section class="card"><h2>Turntable</h2><video controls loop preload="metadata" poster="battery-fitted-v1/preview.jpg" src="battery-fitted-v1/turntable.mp4"></video><p><a href="battery-fitted-v1/metadata.json">All seven proportion estimates and inferred geometry</a></p></section><section class="card"><h2>Preserved generative attempt</h2><img src="battery-reconstruction-v1/candidate-views.jpg" alt="Rejected TripoSR candidate seen from eight directions"><p>TripoSR generated a real watertight mesh on MPS, but it interpreted the occlusion silhouette as a handle-like extension. We preserved and rejected it. Closed topology alone does not establish a correct object.</p><p><a href="battery-reconstruction-v1/model-input.png">Actual reconstruction input</a> · <a href="battery-reconstruction-v1/metadata.json">Model provenance and timings</a></p></section></div>
<h2>Next within Stage 3</h2><p>Improve component shape and appearance with stronger reconstruction and more useful views. Recording-camera extrinsics and physical scale remain unresolved. Exact model-to-video fitting remains Stage 4.</p></main><script>
const meshes=MESH_DATA,canvas=document.getElementById('model'),ctx=canvas.getContext('2d');let selected='fitted',yaw=.8,elevation=.25,zoom=1,drag=null;
function draw(){const mesh=meshes[selected],w=canvas.clientWidth,h=canvas.clientHeight,dpr=devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#142838';ctx.fillRect(0,0,w,h);const vertices=mesh.vertices,c=[0,0,0];for(const p of vertices)for(let k=0;k<3;k++)c[k]+=p[k]/vertices.length;let radius=0;for(const p of vertices)radius=Math.max(radius,Math.hypot(p[0]-c[0],p[1]-c[1],p[2]-c[2]));const scale=Math.min(w,h)*.43*zoom/Math.max(radius,1e-9),cy=Math.cos(yaw),sy=Math.sin(yaw),ce=Math.cos(elevation),se=Math.sin(elevation);function rotate(p){return [cy*p[0]+sy*p[1],se*sy*p[0]-se*cy*p[1]+ce*p[2],-ce*sy*p[0]+ce*cy*p[1]+se*p[2]];}const q=vertices.map(p=>rotate(p.map((x,k)=>x-c[k])));const order=mesh.faces.map((f,i)=>[f.reduce((v,j)=>v+q[j][2],0),i]).sort((a,b)=>a[0]-b[0]);for(const [z,i] of order){const f=mesh.faces[i],n=rotate(mesh.normals[i]),shade=.42+.58*Math.max(0,(-.3*n[0]+.5*n[1]+n[2])/Math.sqrt(1.34)),color=[0,0,0];for(const j of f)for(let k=0;k<3;k++)color[k]+=mesh.colors[j][k]/3;ctx.fillStyle=`rgb(${color.map(v=>Math.round(v*shade)).join(',')})`;ctx.beginPath();f.forEach((j,k)=>{const x=w/2+q[j][0]*scale,y=h/2-q[j][1]*scale;k?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fill();}}
function change(){selected=document.getElementById('model-select').value;const fitted=selected==='fitted';document.getElementById('model-note').textContent=fitted?'Evidence-fitted shape with inferred circular back and end caps. Neutral grey indicates inferred appearance.':'REJECTED: real TripoSR result with incorrect handle-like geometry. Preserved for comparison.';document.getElementById('glb').href=fitted?'battery-fitted-v1/battery.glb':'battery-reconstruction-v1/battery-main.glb';document.getElementById('obj').href=fitted?'battery-fitted-v1/battery.obj':'battery-reconstruction-v1/battery-main.obj';document.getElementById('provenance').href=fitted?'battery-fitted-v1/metadata.json':'battery-reconstruction-v1/metadata.json';draw();}
document.getElementById('model-select').addEventListener('change',change);document.getElementById('angle').addEventListener('input',e=>{yaw=Number(e.target.value)/100;draw()});document.getElementById('reset').addEventListener('click',()=>{yaw=.8;elevation=.25;zoom=1;document.getElementById('angle').value=80;draw()});canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.01;elevation=Math.max(-1.4,Math.min(1.4,elevation+(e.clientY-drag[1])*.01));drag=[e.clientX,e.clientY];draw()});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.2,Math.min(4,zoom*Math.exp(-e.deltaY*.001)));draw()},{passive:false});window.addEventListener('resize',draw);change();
</script></html>'''.replace('ERROR_SUMMARY',summary).replace('ASPECT_RATIO',f"{fitted['length_over_diameter']:.2f}").replace('APPEARANCE_PERCENT',f"{fitted['appearance_evidence_fraction']*100:.0f}").replace('MESH_DATA',json.dumps(meshes,separators=(',',':')))
    out.write_text(doc);print(out)
if __name__=='__main__':main()
